// ---------------------------------------------------------------------------------------------------------------
// helpers

static Bytes H(const char* hex) {
  Bytes b;
  if (!from_hex(hex, b)) {
    std::printf("bad hex literal in test: %s\n", hex);
    b.clear();
  }
  return b;
}
static std::string hx(const Bytes& b) { return to_hex(b, false); }
static Bytes B(const uint8_t* p, size_t n) { return Bytes(p, p + n); }
static Bytes S(const std::string& s) { return Bytes(s.begin(), s.end()); }

static std::string upper(std::string s) {
  for (char& c : s)
    if (c >= 'a' && c <= 'z') c = char(c - 'a' + 'A');
  return s;
}

static bool dec(const char* hex, CborVal& v, std::string* err = nullptr) { return cbor_decode(H(hex), v, err); }
static bool dec_ok(const char* hex) {
  CborVal v;
  return dec(hex, v);
}
static bool rejects(const Bytes& b) {
  CborVal v;
  v.type = CborVal::UInt;
  v.u = 42;
  std::string err;
  bool ok = cbor_decode(b, v, &err);
  // on failure: an error message, and the output left untouched
  return !ok && !err.empty() && v.type == CborVal::UInt && v.u == 42;
}
static bool rejects(const char* hex) { return rejects(H(hex)); }

static double as_double(const CborVal& v) {
  double d;
  std::memcpy(&d, &v.u, 8);
  return d;
}

static std::string rep(const char* unit, size_t n) {
  std::string s;
  for (size_t i = 0; i < n; i++) s += unit;
  return s;
}

// ---------------------------------------------------------------------------------------------------------------
// CBOR writer: RFC 8949 Appendix A encodings + head boundaries

static void test_cbor_writer() {
  CHECK_SECTION("cbor writer: unsigned (RFC 8949 App. A + boundaries)");
  struct U {
    uint64_t v;
    const char* hex;
  } uints[] = {
      {0, "00"},
      {1, "01"},
      {10, "0a"},
      {23, "17"},
      {24, "1818"},
      {25, "1819"},
      {100, "1864"},
      {255, "18ff"},
      {256, "190100"},
      {1000, "1903e8"},
      {65535, "19ffff"},
      {65536, "1a00010000"},
      {1000000, "1a000f4240"},
      {0xFFFFFFFFull, "1affffffff"},
      {0x100000000ull, "1b0000000100000000"},
      {1000000000000ull, "1b000000e8d4a51000"},
      {18446744073709551615ull, "1bffffffffffffffff"},
  };
  for (const U& u : uints) {
    CborWriter w;
    w.uint(u.v);
    CHECK_EQ(hx(w.out()), std::string(u.hex));
  }

  CHECK_SECTION("cbor writer: negative");
  struct N {
    uint64_t v;
    const char* hex;
  } nints[] = {{0, "20"}, {9, "29"}, {99, "3863"}, {999, "3903e7"}, {23, "37"}, {24, "3818"},
               {18446744073709551615ull, "3bffffffffffffffff"}};
  for (const N& n : nints) {
    CborWriter w;
    w.nint(n.v);  // -1 - v : -1, -10, -100, -1000, -24, -25, -18446744073709551616
    CHECK_EQ(hx(w.out()), std::string(n.hex));
  }

  CHECK_SECTION("cbor writer: strings");
  {
    CborWriter w;
    w.bytes(nullptr, 0);
    CHECK_EQ(hx(w.out()), std::string("40"));
  }
  {
    CborWriter w;
    w.bytes(H("01020304"));
    CHECK_EQ(hx(w.out()), std::string("4401020304"));
  }
  {
    CborWriter w;
    Bytes b(24, 0xAB);
    w.bytes(b);
    CHECK_EQ(hx(w.out()), "5818" + hx(b));
  }
  {
    CborWriter w;
    Bytes b(300, 0x01);
    w.bytes(b);
    CHECK_EQ(hx(Bytes(w.out().begin(), w.out().begin() + 3)), std::string("59012c"));
    CHECK_EQ(w.out().size(), size_t(303));
  }
  struct T {
    const char* s;
    const char* hex;
  } texts[] = {{"", "60"},
               {"a", "6161"},
               {"IETF", "6449455446"},
               {"\"\\", "62225c"},
               {"\xc3\xbc", "62c3bc"},
               {"\xe6\xb0\xb4", "63e6b0b4"},
               {"\xf0\x90\x85\x91", "64f0908591"}};
  for (const T& t : texts) {
    CborWriter w;
    w.text(t.s);
    CHECK_EQ(hx(w.out()), std::string(t.hex));
  }

  CHECK_SECTION("cbor writer: containers, tags, simple");
  {
    CborWriter w;
    w.array(0);
    CHECK_EQ(hx(w.out()), std::string("80"));
  }
  {
    CborWriter w;  // [1, [2, 3], [4, 5]]
    w.array(3);
    w.uint(1);
    w.array(2);
    w.uint(2);
    w.uint(3);
    w.array(2);
    w.uint(4);
    w.uint(5);
    CHECK_EQ(hx(w.out()), std::string("8301820203820405"));
  }
  {
    CborWriter w;  // [1..25]
    w.array(25);
    for (uint64_t i = 1; i <= 25; i++) w.uint(i);
    CHECK_EQ(hx(w.out()), std::string("98190102030405060708090a0b0c0d0e0f101112131415161718181819"));
  }
  {
    CborWriter w;
    w.map(0);
    CHECK_EQ(hx(w.out()), std::string("a0"));
  }
  {
    CborWriter w;  // {1: 2, 3: 4}
    w.map(2);
    w.uint(1);
    w.uint(2);
    w.uint(3);
    w.uint(4);
    CHECK_EQ(hx(w.out()), std::string("a201020304"));
  }
  {
    CborWriter w;  // {"a": 1, "b": [2, 3]}
    w.map(2);
    w.text("a");
    w.uint(1);
    w.text("b");
    w.array(2);
    w.uint(2);
    w.uint(3);
    CHECK_EQ(hx(w.out()), std::string("a26161016162820203"));
  }
  {
    CborWriter w;  // ["a", {"b": "c"}]
    w.array(2);
    w.text("a");
    w.map(1);
    w.text("b");
    w.text("c");
    CHECK_EQ(hx(w.out()), std::string("826161a161626163"));
  }
  {
    CborWriter w;  // {"a": "A", ..., "e": "E"}
    w.map(5);
    const char* k[] = {"a", "b", "c", "d", "e"};
    const char* v[] = {"A", "B", "C", "D", "E"};
    for (int i = 0; i < 5; i++) {
      w.text(k[i]);
      w.text(v[i]);
    }
    CHECK_EQ(hx(w.out()), std::string("a56161614161626142616361436164614461656145"));
  }
  {
    CborWriter w;
    w.tag(0);
    w.text("2013-03-21T20:04:00Z");
    CHECK_EQ(hx(w.out()), std::string("c074323031332d30332d32315432303a30343a30305a"));
  }
  {
    CborWriter w;
    w.tag(1);
    w.uint(1363896240);
    CHECK_EQ(hx(w.out()), std::string("c11a514b67b0"));
  }
  {
    CborWriter w;
    w.tag(23);
    w.bytes(H("01020304"));
    CHECK_EQ(hx(w.out()), std::string("d74401020304"));
  }
  {
    CborWriter w;
    w.tag(24);
    w.bytes(H("6449455446"));
    CHECK_EQ(hx(w.out()), std::string("d818456449455446"));
  }
  {
    CborWriter w;
    w.tag(32);
    w.text("http://www.example.com");
    CHECK_EQ(hx(w.out()), std::string("d82076687474703a2f2f7777772e6578616d706c652e636f6d"));
  }
  {
    CborWriter w;
    w.tag(37);  // UUID tag used for request ids
    w.bytes(Bytes(16, 0x11));
    CHECK_EQ(hx(w.out()), "d82550" + rep("11", 16));
  }
  {
    CborWriter w;
    w.boolean(false);
    w.boolean(true);
    w.null();
    CHECK_EQ(hx(w.out()), std::string("f4f5f6"));
    Bytes t = w.take();
    CHECK_EQ(hx(t), std::string("f4f5f6"));
  }
}

// ---------------------------------------------------------------------------------------------------------------
// CBOR decoder: RFC 8949 Appendix A (well-formed), values, limits, malformed

static void test_cbor_decoder_values() {
  CHECK_SECTION("cbor decode: integers");
  CborVal v;
  CHECK(dec("00", v) && v.type == CborVal::UInt && v.u == 0);
  CHECK(dec("17", v) && v.type == CborVal::UInt && v.u == 23);
  CHECK(dec("1818", v) && v.u == 24);
  CHECK(dec("1903e8", v) && v.u == 1000);
  CHECK(dec("1a000f4240", v) && v.u == 1000000);
  CHECK(dec("1b000000e8d4a51000", v) && v.u == 1000000000000ull);
  CHECK(dec("1bffffffffffffffff", v) && v.type == CborVal::UInt && v.u == 18446744073709551615ull);
  CHECK(dec("20", v) && v.type == CborVal::NInt && v.u == 0);    // -1
  CHECK(dec("29", v) && v.type == CborVal::NInt && v.u == 9);    // -10
  CHECK(dec("3863", v) && v.type == CborVal::NInt && v.u == 99);  // -100
  CHECK(dec("3903e7", v) && v.type == CborVal::NInt && v.u == 999);
  CHECK(dec("3bffffffffffffffff", v) && v.type == CborVal::NInt && v.u == 18446744073709551615ull);
  // bignums are just tags 2/3 around a byte string
  CHECK(dec("c249010000000000000000", v) && v.type == CborVal::Tag && v.u == 2 && v.items.size() == 1u &&
        v.items[0].type == CborVal::Bytes_ && hx(v.items[0].b) == "010000000000000000");
  CHECK(dec("c349010000000000000000", v) && v.type == CborVal::Tag && v.u == 3);
  // non-minimal heads are accepted on input (the writer never produces them)
  CHECK(dec("1801", v) && v.type == CborVal::UInt && v.u == 1);
  CHECK(dec("1b0000000000000001", v) && v.u == 1);
  CHECK(dec("5a0000000161", v) && v.type == CborVal::Bytes_ && hx(v.b) == "61");

  CHECK_SECTION("cbor decode: floats and simple values");
  CHECK(dec("f90000", v) && v.type == CborVal::Float && as_double(v) == 0.0 && !std::signbit(as_double(v)));
  CHECK(dec("f98000", v) && as_double(v) == 0.0 && std::signbit(as_double(v)));
  CHECK(dec("f93c00", v) && as_double(v) == 1.0);
  CHECK(dec("fb3ff199999999999a", v) && as_double(v) == 1.1);
  CHECK(dec("f93e00", v) && as_double(v) == 1.5);
  CHECK(dec("f97bff", v) && as_double(v) == 65504.0);
  CHECK(dec("fa47c35000", v) && as_double(v) == 100000.0);
  CHECK(dec("fa7f7fffff", v) && as_double(v) == 3.4028234663852886e+38);
  CHECK(dec("fb7e37e43c8800759c", v) && as_double(v) == 1.0e+300);
  CHECK(dec("f90001", v) && as_double(v) == std::ldexp(1.0, -24));  // 5.960464477539063e-8
  CHECK(dec("f90400", v) && as_double(v) == 0.00006103515625);
  CHECK(dec("f9c400", v) && as_double(v) == -4.0);
  CHECK(dec("fbc010666666666666", v) && as_double(v) == -4.1);
  CHECK(dec("f97c00", v) && std::isinf(as_double(v)) && as_double(v) > 0);
  CHECK(dec("f97e00", v) && std::isnan(as_double(v)));
  CHECK(dec("f9fc00", v) && std::isinf(as_double(v)) && as_double(v) < 0);
  CHECK(dec("fa7f800000", v) && std::isinf(as_double(v)) && as_double(v) > 0);
  CHECK(dec("fa7fc00000", v) && std::isnan(as_double(v)));
  CHECK(dec("faff800000", v) && std::isinf(as_double(v)) && as_double(v) < 0);
  CHECK(dec("fb7ff0000000000000", v) && std::isinf(as_double(v)));
  CHECK(dec("fb7ff8000000000000", v) && std::isnan(as_double(v)));
  CHECK(dec("fbfff0000000000000", v) && std::isinf(as_double(v)) && as_double(v) < 0);
  CHECK(dec("fa00000001", v) && as_double(v) == std::ldexp(1.0, -149));  // smallest single subnormal
  CHECK(dec("f903ff", v) && as_double(v) == std::ldexp(1023.0, -24));     // largest half subnormal
  CHECK(dec("f4", v) && v.type == CborVal::Bool && v.u == 0);
  CHECK(dec("f5", v) && v.type == CborVal::Bool && v.u == 1);
  CHECK(dec("f6", v) && v.type == CborVal::Null);
  CHECK(dec("f7", v) && v.type == CborVal::Undefined);
  CHECK(rejects("f0"));    // simple(16): unassigned, not representable
  CHECK(rejects("f8ff"));  // simple(255)
  CHECK(rejects("f818"));  // two-byte simple < 32: not well-formed

  CHECK_SECTION("cbor decode: strings, tags");
  CHECK(dec("40", v) && v.type == CborVal::Bytes_ && v.b.empty());
  CHECK(dec("4401020304", v) && v.type == CborVal::Bytes_ && hx(v.b) == "01020304");
  CHECK(dec("60", v) && v.type == CborVal::Text && v.str().empty());
  CHECK(dec("6449455446", v) && v.type == CborVal::Text && v.str() == "IETF");
  CHECK(dec("62225c", v) && v.str() == "\"\\");
  CHECK(dec("62c3bc", v) && v.str() == "\xc3\xbc");
  CHECK(dec("63e6b0b4", v) && v.str() == "\xe6\xb0\xb4");
  CHECK(dec("64f0908591", v) && v.str() == "\xf0\x90\x85\x91");
  CHECK(dec("c074323031332d30332d32315432303a30343a30305a", v) && v.type == CborVal::Tag && v.u == 0 &&
        v.items.size() == 1u && v.items[0].str() == "2013-03-21T20:04:00Z");
  CHECK(dec("c11a514b67b0", v) && v.u == 1 && v.items[0].type == CborVal::UInt && v.items[0].u == 1363896240);
  CHECK(dec("c1fb41d452d9ec200000", v) && v.u == 1 && v.items[0].type == CborVal::Float &&
        as_double(v.items[0]) == 1363896240.5);
  CHECK(dec("d74401020304", v) && v.u == 23 && hx(v.items[0].b) == "01020304");
  CHECK(dec("d818456449455446", v) && v.u == 24 && hx(v.items[0].b) == "6449455446");
  CHECK(dec("d82076687474703a2f2f7777772e6578616d706c652e636f6d", v) && v.u == 32 &&
        v.items[0].str() == "http://www.example.com");

  CHECK_SECTION("cbor decode: arrays and maps");
  CHECK(dec("80", v) && v.type == CborVal::Array && v.items.empty());
  CHECK(dec("83010203", v) && v.items.size() == 3u && v.items[2].u == 3);
  CHECK(dec("8301820203820405", v) && v.items.size() == 3u && v.items[1].type == CborVal::Array &&
        v.items[2].items[1].u == 5);
  CHECK(dec("98190102030405060708090a0b0c0d0e0f101112131415161718181819", v) && v.items.size() == 25u &&
        v.items[24].u == 25);
  CHECK(dec("a0", v) && v.type == CborVal::Map && v.items.empty());
  CHECK(dec("a201020304", v) && v.type == CborVal::Map && v.items.size() == 4u);
  {
    const CborVal* a = cbor_get(v, 1);
    const CborVal* b = cbor_get(v, 3);
    CHECK(a && a->type == CborVal::UInt && a->u == 2);
    CHECK(b && b->u == 4);
    CHECK(cbor_get(v, 2) == nullptr);  // 2 is a value, not a key
    CHECK(cbor_get(v, 4) == nullptr);
  }
  CHECK(dec("a26161016162820203", v) && v.items[0].str() == "a" && v.items[3].items.size() == 2u);
  CHECK(cbor_get(v, 1) == nullptr);  // text keys are not found by uint lookup
  CHECK(dec("826161a161626163", v) && v.items[1].type == CborVal::Map && v.items[1].items[1].str() == "c");
  CHECK(dec("a56161614161626142616361436164614461656145", v) && v.items.size() == 10u && v.items[9].str() == "E");
  CHECK(dec("83010203", v) && cbor_get(v, 0) == nullptr);  // not a map
  CHECK(dec("a1200a", v) && cbor_get(v, 0) == nullptr);    // key -1 is not key 0
}

static void test_cbor_decoder_malformed() {
  CHECK_SECTION("cbor decode: indefinite lengths rejected (RFC 8949 App. A)");
  CHECK(rejects("5f42010243030405ff"));
  CHECK(rejects("7f657374726561646d696e67ff"));
  CHECK(rejects("9fff"));
  CHECK(rejects("9f018202039f0405ffff"));
  CHECK(rejects("9f01820203820405ff"));
  CHECK(rejects("83018202039f0405ff"));
  CHECK(rejects("83019f0203ff820405"));
  CHECK(rejects("bf61610161629f0203ffff"));
  CHECK(rejects("826161bf61626163ff"));
  CHECK(rejects("bf6346756ef563416d7421ff"));
  CHECK(rejects("1f"));  // indefinite on int: malformed
  CHECK(rejects("3f"));
  CHECK(rejects("df00"));  // indefinite tag
  CHECK(rejects("ff"));    // stray break

  CHECK_SECTION("cbor decode: truncated / reserved / trailing");
  CHECK(rejects(Bytes()));
  {
    CborVal v;
    CHECK(!cbor_decode(nullptr, 0, v));
  }
  const char* bad[] = {"18", "1900", "1a000000", "1b00000000000000", "38", "5801", "4201", "6261", "7801", "81",
                       "8201", "a1", "a101", "a20102", "c0", "d8", "d825", "f9", "f900", "fa000000", "fb00000000000000",
                       "f8", "1c", "1d", "1e", "3c", "5c", "7c", "9c", "bc", "dc", "fc", "fd", "fe", "0000", "8000",
                       "a0a0", "f6f6", "83010203ff", "4000", "60ff"};
  for (const char* h : bad)
    if (!CHECK(rejects(h))) std::printf("     input %s\n", h);
  // declared lengths far beyond the input must fail without allocating them
  CHECK(rejects("5bffffffffffffffff"));
  CHECK(rejects("5b000000010000000000"));
  CHECK(rejects("7bffffffffffffffff"));
  CHECK(rejects("9bffffffffffffffff"));
  CHECK(rejects("bbffffffffffffffff"));
  CHECK(rejects("9a00000100"));  // 256 elements declared, none present
  CHECK(rejects("5aff000000"));

  CHECK_SECTION("cbor decode: invalid UTF-8 text rejected");
  const char* badtext[] = {"61ff", "6180", "62c080", "62c1bf", "63e08080", "63eda080", "64f4908080", "64f8888080",
                           "62c328", "61c3"};
  for (const char* h : badtext)
    if (!CHECK(rejects(h))) std::printf("     input %s\n", h);
  CHECK(dec_ok("63efbfbf"));    // U+FFFF
  CHECK(dec_ok("64f48fbfbf"));  // U+10FFFF
  CHECK(dec_ok("63ed9fbf"));    // U+D7FF

  CHECK_SECTION("cbor decode: duplicate map keys rejected");
  CHECK(rejects("a201020103"));
  CHECK(rejects("a20102180103"));        // same key 1, non-minimal head
  CHECK(rejects("a26161016161f6"));      // "a" twice
  CHECK(rejects("a2410001410002"));      // h'00' twice
  CHECK(rejects("a2820102f6820102f6"));  // [1,2] twice
  CHECK(rejects("a3010002000100"));      // 1, 2, 1
  CHECK(rejects("a2c10100c10100"));      // tagged keys
  CHECK(dec_ok("a2616101416102"));       // "a" vs h'61': different types
  CHECK(dec_ok("a2200000f6"));           // -1 vs 0
  CHECK(dec_ok("a2c10100c20100"));       // 1(1) vs 2(1)
  CHECK(dec_ok("a2a10102f6a10103f6"));   // {1:2} vs {1:3}

  CHECK_SECTION("cbor decode: nesting depth <= 8");
  CHECK(dec_ok((rep("81", 7) + "80").c_str()));        // 8 nested arrays
  CHECK(rejects((rep("81", 8) + "80").c_str()));       // 9
  CHECK(dec_ok((rep("81", 7) + "00").c_str()));        // scalar inside the 7th
  CHECK(dec_ok((rep("c1", 8) + "00").c_str()));        // 8 nested tags
  CHECK(rejects((rep("c1", 9) + "00").c_str()));       // 9
  CHECK(dec_ok((rep("a101", 7) + "a0").c_str()));      // 8 nested maps
  CHECK(rejects((rep("a101", 8) + "a0").c_str()));     // 9
  CHECK(dec_ok((rep("81", 6) + "c180").c_str()));      // arrays + tag + array = 8
  CHECK(rejects((rep("81", 7) + "c180").c_str()));     // 9
  CHECK(rejects((rep("81", 100) + "00").c_str()));     // deep garbage
  CHECK(rejects((rep("9f", 1000) + "00").c_str()));

  CHECK_SECTION("cbor decode: <= 256 items per container");
  CHECK(dec_ok(("990100" + rep("00", 256)).c_str()));
  CHECK(rejects(("990101" + rep("00", 257)).c_str()));
  {
    std::string m = "b90100";
    for (int k = 0; k < 256; k++) {
      char buf[16];
      std::snprintf(buf, sizeof buf, k < 24 ? "%02x00" : "18%02x00", k);
      m += buf;
    }
    CHECK(dec_ok(m.c_str()));
    std::string m2 = "b90101" + m.substr(6) + "19010000";  // 257 distinct keys
    CHECK(rejects(m2.c_str()));
  }
}

static void test_cbor_roundtrip() {
  CHECK_SECTION("cbor round trip: protocol-like request");
  CborWriter w;
  w.map(8);
  w.uint(1);
  w.tag(37);
  w.bytes(Bytes(16, 0xA5));
  w.uint(2);
  w.uint(10143);
  w.uint(3);
  w.bytes(Bytes(20, 0x11));
  w.uint(8);
  w.bytes(H("0de0b6b3a7640000"));
  w.uint(9);
  w.bytes(Bytes(68, 0x42));
  w.uint(11);
  w.uint(0xFFFFFFFFFFull);
  w.uint(12);
  w.map(2);
  w.uint(1);
  w.text("nansen");
  w.uint(4);
  w.uint(3);
  w.uint(16);
  w.text("AUSD");
  CborVal v;
  std::string err;
  CHECK(cbor_decode(w.out(), v, &err));
  CHECK_EQ(err, std::string());
  CHECK(v.type == CborVal::Map && v.items.size() == 16u);
  const CborVal* id = cbor_get(v, 1);
  CHECK(id && id->type == CborVal::Tag && id->u == 37 && id->items[0].b == Bytes(16, 0xA5));
  const CborVal* chain = cbor_get(v, 2);
  CHECK(chain && chain->type == CborVal::UInt && chain->u == 10143);
  const CborVal* val = cbor_get(v, 8);
  CHECK(val && val->type == CborVal::Bytes_ && hx(val->b) == "0de0b6b3a7640000");
  const CborVal* cd = cbor_get(v, 9);
  CHECK(cd && cd->b.size() == 68u);
  const CborVal* exp = cbor_get(v, 11);
  CHECK(exp && exp->u == 0xFFFFFFFFFFull);
  const CborVal* risk = cbor_get(v, 12);
  CHECK(risk && risk->type == CborVal::Map && cbor_get(*risk, 1) && cbor_get(*risk, 1)->str() == "nansen");
  CHECK(risk && cbor_get(*risk, 4) && cbor_get(*risk, 4)->u == 3);
  const CborVal* sym = cbor_get(v, 16);
  CHECK(sym && sym->type == CborVal::Text && sym->str() == "AUSD");
  CHECK(cbor_get(v, 5) == nullptr);
  // every strict prefix is truncated, and one extra byte is trailing
  const Bytes& all = w.out();
  bool all_prefixes_rejected = true;
  for (size_t n = 0; n < all.size(); n++)
    if (!rejects(Bytes(all.begin(), all.begin() + std::ptrdiff_t(n)))) all_prefixes_rejected = false;
  CHECK(all_prefixes_rejected);
  Bytes extra = all;
  extra.push_back(0x00);
  CHECK(rejects(extra));
}

