// Feeds parts; returns the 1-based index of the part that returned Complete (0 = never); every other part must be
// Accepted (and complete() false before the last).
static size_t feed(UrDecoder& d, const char* const* parts, size_t n, bool up = false) {
  for (size_t i = 0; i < n; i++) {
    std::string p = up ? upper(parts[i]) : std::string(parts[i]);
    UrDecoder::Result r = d.receive(p);
    if (r == UrDecoder::Complete) return i + 1;
    if (r != UrDecoder::Accepted) {
      std::printf("     part %u -> result %d (%s)\n", unsigned(i + 1), int(r), d.error().c_str());
      return 0;
    }
    if (d.complete()) return 0;
  }
  return 0;
}

static void test_ur_multipart_official() {
  CHECK_SECTION("ur multipart: official bc-ur parts, pure 1..9");
  const Bytes want = B(kWolf256Cbor, sizeof kWolf256Cbor);
  CHECK_EQ(crc32(want.data(), want.size()), kWolf256Crc);
  UrDecoder d;
  CHECK(d.progress() == 0.0f);
  for (size_t i = 0; i < 8; i++) {
    CHECK_EQ(d.receive(kOfficialParts[i]), UrDecoder::Accepted);
    CHECK_EQ(d.seq_len(), size_t(9));
    CHECK_EQ(d.received_pure(), i + 1);
    CHECK(std::fabs(d.progress() - float(i + 1) / 9.0f) < 1e-6f);
  }
  CHECK_EQ(d.receive(kOfficialParts[8]), UrDecoder::Complete);
  CHECK(d.complete() && d.type() == "bytes" && d.message() == want);
  CHECK(d.progress() == 1.0f);

  CHECK_SECTION("ur multipart: official parts 20..1 (mixed first)");
  d.reset();
  std::vector<const char*> rev(kOfficialParts, kOfficialParts + 20);
  std::reverse(rev.begin(), rev.end());
  // GF(2) rank of parts 20,19,... reaches 9 at the 16th part (tools/ref_ur.py gf2_complete_at)
  CHECK_EQ(feed(d, rev.data(), rev.size()), size_t(16));
  CHECK(d.message() == want);

  CHECK_SECTION("ur multipart: official mixed parts 10..20 only (rank 8 of 9: must not complete)");
  d.reset();
  CHECK_EQ(feed(d, kOfficialParts + 9, 11), size_t(0));
  CHECK(!d.complete());
  CHECK(std::fabs(d.progress() - 8.0f / 9.0f) < 1e-6f);
  // pure parts 1..4 add nothing new; part 5 (fragment 4) is the missing dimension
  for (size_t i = 0; i < 4; i++) CHECK_EQ(d.receive(kOfficialParts[i]), UrDecoder::Accepted);
  CHECK(std::fabs(d.progress() - 8.0f / 9.0f) < 1e-6f);
  CHECK_EQ(d.receive(kOfficialParts[4]), UrDecoder::Complete);
  CHECK(d.message() == want);

  CHECK_SECTION("ur multipart: BCR-2020-005 ur:seed 1-3 + generated parts");
  d.reset();
  CHECK_EQ(d.receive(kSeedParts[4]), UrDecoder::Accepted);  // 5-3 = {0,1,2}
  CHECK_EQ(d.received_pure(), size_t(0));
  CHECK(std::fabs(d.progress() - 1.0f / 3.0f) < 1e-6f);
  CHECK_EQ(d.receive(kSeedParts[3]), UrDecoder::Accepted);  // 4-3 = {0,2}  -> fragment 1 solved
  CHECK_EQ(d.received_pure(), size_t(1));
  CHECK(std::fabs(d.progress() - 2.0f / 3.0f) < 1e-6f);
  CHECK_EQ(d.receive(kSeedParts[5]), UrDecoder::Accepted);  // 6-3 = {1}: nothing new
  CHECK(std::fabs(d.progress() - 2.0f / 3.0f) < 1e-6f);
  CHECK_EQ(d.receive(kSeedParts[0]), UrDecoder::Complete);  // 1-3 = {0}: the spec's own part
  CHECK(d.message() == B(kSeedMsg, sizeof kSeedMsg));
}

static void test_ur_multipart_streams() {
  const Bytes want = B(kStreamMsg, sizeof kStreamMsg);
  UrDecoder d;

  CHECK_SECTION("ur multipart: python stream, mixed parts only");
  CHECK_EQ(feed(d, kStreamMixed, kStreamMixedCount), kStreamMixedCount);
  CHECK(d.message() == want && d.type() == "ripar-cosign-req");
  CborVal v;
  CHECK(cbor_decode(d.message(), v) && cbor_get(v, 2) && cbor_get(v, 2)->u == 10143);

  CHECK_SECTION("ur multipart: python stream, mixed parts only, upper case");
  d.reset();
  CHECK_EQ(feed(d, kStreamMixed, kStreamMixedCount, true), kStreamMixedCount);
  CHECK(d.message() == want);

  CHECK_SECTION("ur multipart: pure parts out of order with duplicates");
  d.reset();
  CHECK_EQ(feed(d, kStreamPureShuffled, kStreamPureShuffledCount), kStreamPureShuffledCount);
  CHECK(d.message() == want);

  CHECK_SECTION("ur multipart: 5 pure parts + later mixed parts");
  d.reset();
  CHECK_EQ(feed(d, kStreamCombo, kStreamComboCount), kStreamComboCount);
  CHECK(d.message() == want);

  CHECK_SECTION("ur multipart: every mixed part twice");
  d.reset();
  {
    size_t done = 0;
    for (size_t i = 0; i < kStreamMixedCount && !done; i++) {
      for (int rep2 = 0; rep2 < 2 && !done; rep2++) {
        UrDecoder::Result r = d.receive(kStreamMixed[i]);
        if (r == UrDecoder::Complete) done = i + 1;
        else CHECK_EQ(r, UrDecoder::Accepted);
      }
    }
    CHECK_EQ(done, kStreamMixedCount);
    CHECK(d.message() == want);
  }

  CHECK_SECTION("ur multipart: noise, other types and bad frames keep the progress");
  d.reset();
  {
    size_t done = 0;
    for (size_t i = 0; i < kStreamMixedCount && !done; i++) {
      const float before = d.progress();
      CHECK_EQ(d.receive("not a ur"), UrDecoder::Ignored);
      if (i > 0) CHECK_EQ(d.receive(kOfficialParts[0]), UrDecoder::Ignored);  // other type while in progress
      if (i > 0) CHECK_EQ(d.receive("ur:bytes/aeadaolazmjendeoti"), UrDecoder::Ignored);
      std::string bad = kStreamMixed[i];
      bad[bad.size() - 3] = bad[bad.size() - 3] == 'a' ? 'e' : 'a';  // corrupt one letter
      CHECK_EQ(d.receive(bad), UrDecoder::Error);
      CHECK(!d.error().empty());
      CHECK(d.progress() == before);
      UrDecoder::Result r = d.receive(kStreamMixed[i]);
      if (r == UrDecoder::Complete) done = i + 1;
      else CHECK_EQ(r, UrDecoder::Accepted);
    }
    CHECK_EQ(done, kStreamMixedCount);
    CHECK(d.message() == want);
  }

  CHECK_SECTION("ur multipart: a different message of the same type starts over");
  d.reset();
  CHECK_EQ(d.receive(kStreamMixed[0]), UrDecoder::Accepted);
  CHECK_EQ(d.receive(kStreamMixed[1]), UrDecoder::Accepted);
  CHECK_EQ(d.receive(kStreamPureShuffled[0]), UrDecoder::Accepted);
  CHECK_EQ(d.seq_len(), kStreamSeqLen);
  CHECK_EQ(feed(d, kStream2Pure, kStream2Count), kStream2Count);
  CHECK(d.message() == B(kStream2Msg, sizeof kStream2Msg));

  CHECK_SECTION("ur multipart: single-part UR of the same type completes");
  d.reset();
  CHECK_EQ(d.receive(kStreamMixed[0]), UrDecoder::Accepted);
  CHECK_EQ(d.receive(ur_encode("ripar-cosign-req", B(kSmallCbor, sizeof kSmallCbor))), UrDecoder::Complete);
  CHECK(d.message() == B(kSmallCbor, sizeof kSmallCbor));
}

// builds "ur:<type>/<n>-<len>/<bytewords of [seqNum, seqLen, msgLen, checksum, frag]>"
static std::string make_part(const char* type, uint64_t seq_num, uint64_t seq_len, uint64_t msg_len, uint64_t sum,
                             const Bytes& frag, const char* path = nullptr) {
  CborWriter w;
  w.array(5);
  w.uint(seq_num);
  w.uint(seq_len);
  w.uint(msg_len);
  w.uint(sum);
  w.bytes(frag);
  char buf[64];
  if (path)
    std::snprintf(buf, sizeof buf, "%s", path);
  else
    std::snprintf(buf, sizeof buf, "%lu-%lu", (unsigned long)seq_num, (unsigned long)seq_len);
  return std::string("ur:") + type + "/" + buf + "/" + bytewords_minimal_encode(w.out());
}

static void test_ur_multipart_crafted() {
  CHECK_SECTION("ur multipart: crafted parts (own encoder, pure + xor)");
  const Bytes msg = S("Ripar Wallet fountain test message!");  // 35 bytes -> 4 fragments of 9 (1 pad byte)
  const uint32_t sum = crc32(msg.data(), msg.size());
  std::vector<Bytes> fr(4);
  for (size_t i = 0; i < 4; i++) {
    fr[i].assign(9, 0);
    for (size_t k = 0; k < 9 && i * 9 + k < msg.size(); k++) fr[i][k] = msg[i * 9 + k];
  }
  UrDecoder d;
  CHECK_EQ(d.receive(make_part("t", 3, 4, 35, sum, fr[2])), UrDecoder::Accepted);
  CHECK_EQ(d.receive(make_part("t", 1, 4, 35, sum, fr[0])), UrDecoder::Accepted);
  CHECK_EQ(d.receive(make_part("t", 4, 4, 35, sum, fr[3])), UrDecoder::Accepted);
  CHECK_EQ(d.receive(make_part("t", 1, 4, 35, sum, fr[0])), UrDecoder::Accepted);  // duplicate
  CHECK_EQ(d.received_pure(), size_t(3));
  CHECK_EQ(d.receive(make_part("t", 2, 4, 35, sum, fr[1])), UrDecoder::Complete);
  CHECK(d.message() == msg);

  // mixed parts built from ur_choose_fragments (ties the decoder to the selection function)
  d.reset();
  size_t done = 0;
  for (uint32_t s = 5; s < 60 && !done; s++) {
    std::vector<size_t> idx = ur_choose_fragments(s, 4, sum);
    Bytes x(9, 0);
    for (size_t i : idx)
      for (size_t k = 0; k < 9; k++) x[k] ^= fr[i][k];
    UrDecoder::Result r = d.receive(make_part("t", s, 4, 35, sum, x));
    if (r == UrDecoder::Complete) done = s;
    else if (!CHECK_EQ(r, UrDecoder::Accepted)) break;
  }
  CHECK(done != 0);
  CHECK(d.message() == msg);

  CHECK_SECTION("ur multipart: single fragment message (1-1)");
  d.reset();
  CHECK_EQ(d.receive(make_part("t", 1, 1, 3, crc32(msg.data(), 3), Bytes(msg.begin(), msg.begin() + 3))),
           UrDecoder::Complete);
  CHECK(d.message() == Bytes(msg.begin(), msg.begin() + 3));

  CHECK_SECTION("ur multipart: message checksum mismatch");
  d.reset();
  CHECK_EQ(d.receive(make_part("t", 1, 4, 35, sum ^ 1, fr[0])), UrDecoder::Accepted);
  CHECK_EQ(d.receive(make_part("t", 2, 4, 35, sum ^ 1, fr[1])), UrDecoder::Accepted);
  CHECK_EQ(d.receive(make_part("t", 3, 4, 35, sum ^ 1, fr[2])), UrDecoder::Accepted);
  CHECK_EQ(d.receive(make_part("t", 4, 4, 35, sum ^ 1, fr[3])), UrDecoder::Error);
  CHECK(!d.complete() && d.seq_len() == 0u && !d.error().empty());
  // afterwards a good stream decodes
  for (size_t i = 0; i < 3; i++) CHECK_EQ(d.receive(make_part("t", i + 1, 4, 35, sum, fr[i])), UrDecoder::Accepted);
  CHECK_EQ(d.receive(make_part("t", 4, 4, 35, sum, fr[3])), UrDecoder::Complete);
  CHECK(d.message() == msg);

  CHECK_SECTION("ur multipart: malformed parts -> Error, progress kept");
  d.reset();
  CHECK_EQ(d.receive(make_part("t", 1, 4, 35, sum, fr[0])), UrDecoder::Accepted);
  const Bytes f9(9, 7);
  struct Bad {
    std::string part;
    const char* why;
  } bads[] = {
      {make_part("t", 2, 4, 35, sum, fr[1], "3-4"), "path seqNum differs from CBOR"},
      {make_part("t", 2, 4, 35, sum, fr[1], "2-5"), "path seqLen differs from CBOR"},
      {make_part("t", 2, 4, 35, sum, fr[1], "0-4"), "path seqNum 0"},
      {make_part("t", 2, 4, 35, sum, fr[1], "2-0"), "path seqLen 0"},
      {make_part("t", 2, 4, 35, sum, fr[1], "2"), "path without dash"},
      {make_part("t", 2, 4, 35, sum, fr[1], "-4"), "path empty seqNum"},
      {make_part("t", 2, 4, 35, sum, fr[1], "2-"), "path empty seqLen"},
      {make_part("t", 2, 4, 35, sum, fr[1], "x-4"), "path not decimal"},
      {make_part("t", 2, 4, 35, sum, fr[1], "2-4-1"), "path two dashes"},
      {make_part("t", 2, 4, 35, sum, fr[1], "99999999999-4"), "path seqNum overflow"},
      {make_part("t", 0, 4, 35, sum, fr[1], "0-4"), "seqNum 0"},
      {make_part("t", 2, 5, 35, sum, fr[1]), "seqLen inconsistent with msgLen/fragLen"},
      {make_part("t", 2, 4, 0, sum, fr[1]), "msgLen 0"},
      {make_part("t", 2, 4, 35, sum, Bytes()), "empty fragment"},
      {make_part("t", 2, 200, 1800, sum, f9), "seqLen above limit"},
      {make_part("t", 2, 2, 9000, sum, Bytes(4500, 1)), "message above limit"},
      {make_part("t", 0x100000000ull, 4, 35, sum, fr[1], "4294967295-4"), "seqNum > 32 bit"},
      {make_part("t", 2, 4, 35, 0x100000000ull, fr[1]), "checksum > 32 bit"},
      {"ur:t/2-4/" + bytewords_minimal_encode(H("8402041823f6")), "array of 4"},
      {"ur:t/2-4/" + bytewords_minimal_encode(H("85020418230169000000000000000000")), "fragment is text"},
      {"ur:t/2-4/" + bytewords_minimal_encode(H("8502041823f64900000000000000000000")), "checksum not uint"},
      {"ur:t/2-4/" + bytewords_minimal_encode(H("a0")), "not an array"},
      {"ur:t/2-4/" + bytewords_minimal_encode(H("9f02041823f6ff")), "indefinite array"},
      {"ur:t/2-4/aeadaolazmjendeota", "bad bytewords CRC"},
      {"ur:t/2-4/", "empty body"},
      {"ur:t/2-4/x/y", "too many components"},
  };
  size_t nbad = sizeof bads / sizeof bads[0];
  for (size_t i = 0; i < nbad; i++) {
    const float before = d.progress();
    UrDecoder::Result r = d.receive(bads[i].part);
    if (!CHECK_EQ(r, UrDecoder::Error)) std::printf("     case: %s\n", bads[i].why);
    if (!CHECK(d.progress() == before && d.seq_len() == 4u)) std::printf("     case: %s\n", bads[i].why);
  }
  for (size_t i = 1; i < 3; i++) CHECK_EQ(d.receive(make_part("t", i + 1, 4, 35, sum, fr[i])), UrDecoder::Accepted);
  CHECK_EQ(d.receive(make_part("t", 4, 4, 35, sum, fr[3])), UrDecoder::Complete);
  CHECK(d.message() == msg);

  CHECK_SECTION("ur multipart: consistent part of another message restarts");
  d.reset();
  CHECK_EQ(d.receive(make_part("t", 1, 4, 35, sum, fr[0])), UrDecoder::Accepted);
  CHECK_EQ(d.receive(make_part("t", 2, 4, 36, sum, fr[1])), UrDecoder::Accepted);  // msgLen differs
  CHECK_EQ(d.received_pure(), size_t(1));
  CHECK_EQ(d.receive(make_part("t", 2, 4, 35, sum ^ 2, fr[1])), UrDecoder::Accepted);  // checksum differs
  CHECK_EQ(d.received_pure(), size_t(1));
  CHECK_EQ(d.receive(make_part("t", 2, 3, 27, sum, fr[1])), UrDecoder::Accepted);  // seqLen differs
  CHECK_EQ(d.seq_len(), size_t(3));
  CHECK_EQ(d.receive(make_part("t", 2, 4, 35, sum, Bytes(fr[1].begin(), fr[1].begin() + 8), "2-5")),
           UrDecoder::Error);  // 35/8 -> 5 fragments, path says 5 but CBOR says 4

  CHECK_SECTION("ur multipart: limits accepted at the edge");
  d.reset();
  {
    // 128 fragments of 64 bytes = 8192-byte message: pure parts in reverse order
    Bytes big(8192);
    for (size_t i = 0; i < big.size(); i++) big[i] = uint8_t(i * 13 + 5);
    const uint32_t bs = crc32(big.data(), big.size());
    UrDecoder::Result r = UrDecoder::Accepted;
    for (size_t k = 128; k >= 1 && r == UrDecoder::Accepted; k--)
      r = d.receive(make_part("big", k, 128, 8192, bs, Bytes(big.begin() + std::ptrdiff_t((k - 1) * 64),
                                                             big.begin() + std::ptrdiff_t(k * 64))));
    CHECK_EQ(r, UrDecoder::Complete);
    CHECK(d.message() == big);
  }
}

int main() {
  test_cbor_writer();
  test_cbor_decoder_values();
  test_cbor_decoder_malformed();
  test_cbor_roundtrip();
  test_bytewords();
  test_ur_single();
  test_choose_fragments();
  test_ur_multipart_official();
  test_ur_multipart_streams();
  test_ur_multipart_crafted();
  return CHECK_SUMMARY();
}
